"""Stage a single benchmark split and run the bundled code on a Kaggle GPU."""

import hashlib
import json
import os
import shutil
import subprocess
import sys
import tempfile
import traceback
from pathlib import Path


def run_logged(command, cwd, log_file):
    with log_file.open("w", encoding="utf-8") as log:
        with subprocess.Popen(
            command, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, encoding="utf-8", errors="replace",
        ) as proc:
            for line in proc.stdout:
                print(line, end="", flush=True)
                log.write(line)
                log.flush()
            code = proc.wait()
    if code:
        raise subprocess.CalledProcessError(code, command)


def run(split, sources, source_digest):
    output = Path("/kaggle/working/results/maze")
    output.mkdir(parents=True, exist_ok=True)
    run_record = {
        "split": split,
        "is_private_requested": True,
        "accelerator_requested": "NvidiaTeslaT4",
        "dataset": "sapientinc/maze-30x30-hard-1k",
        "revision": "549754de3d67eebe57b6b22c7d226b9412d55b07",
        "source_bundle_sha256": source_digest,
    }
    scratch = Path("/kaggle/temp")
    scratch.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=scratch) as directory:
        root = Path(directory)
        results = root / "results/maze"
        results.mkdir(parents=True)
        try:
            import torch
            from huggingface_hub import hf_hub_download

            torch.set_num_threads(4)
            if not torch.cuda.is_available():
                raise RuntimeError("The requested CUDA GPU is unavailable")
            run_record["gpu"] = torch.cuda.get_device_name(0)
            run_record["cuda"] = torch.version.cuda
            run_record["pytorch"] = str(torch.__version__)
            print(json.dumps(run_record), flush=True)
            for name, content in sources.items():
                target = root / "src/maze" / name
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(content, encoding="utf-8", newline="\n")
            backend_log = output / "backend.log"
            run_logged([sys.executable, "-u", "src/maze/check_backend.py"], root, backend_log)
            reports = [
                line for line in backend_log.read_text(encoding="utf-8").splitlines()
                if line.startswith("{") and '"backend_check"' in line
            ]
            if not reports or json.loads(reports[-1]).get("backend_check") != "passed":
                raise RuntimeError("Backend comparison did not report a passing result")
            (output / "backend.json").write_text(reports[-1] + "\n", encoding="utf-8")
            filename = {"dev": "train.csv", "test": "test.csv"}[split]
            dataset_file = Path(hf_hub_download(
                repo_id=run_record["dataset"], repo_type="dataset",
                filename=filename, revision=run_record["revision"],
                cache_dir=str(root / "hf-cache"),
            ))
            data = root / "data/maze" / filename
            data.parent.mkdir(parents=True)
            shutil.copyfile(dataset_file, data)
            run_record["dataset_sha256"] = hashlib.sha256(data.read_bytes()).hexdigest()
            command = [sys.executable, "-u", "src/maze/evaluate.py", "--split", split]
            run_logged(command, root, output / "evaluation.log")
            if not any(path.is_file() for path in results.rglob("*")):
                raise RuntimeError("Evaluation exited successfully but saved no result files")
            run_record["status"] = "complete"
        except BaseException:
            run_record["status"] = "failed"
            (output / "failure.txt").write_text(traceback.format_exc(), encoding="utf-8")
            raise
        finally:
            shutil.copytree(results, output, dirs_exist_ok=True)
            (output / "runtime.json").write_text(
                json.dumps(run_record, indent=2) + "\n", encoding="utf-8"
            )


os.environ.setdefault("HF_HUB_DISABLE_XET", "1")
for setting in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS"):
    os.environ[setting] = "4"

run('dev', json.loads('{"audit.py": "\\"\\"\\"Verify the official development split using a scorer-side BFS oracle.\\"\\"\\"\\n\\nimport csv\\nimport hashlib\\nimport json\\nfrom collections import Counter, deque\\nfrom itertools import permutations\\nfrom pathlib import Path\\n\\n\\nROOT = Path(__file__).resolve().parents[2]\\nREVISION = \\"549754de3d67eebe57b6b22c7d226b9412d55b07\\"\\nSIDE = 30\\nDIRECTIONS = {-SIDE: \\"U\\", SIDE: \\"D\\", -1: \\"L\\", 1: \\"R\\"}\\nORDERS = [\\"\\".join(order) for order in permutations(\\"UDLR\\")]\\n\\n\\ndef neighbors(index):\\n    row, col = divmod(index, SIDE)\\n    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):\\n        y, x = row + dy, col + dx\\n        if 0 <= y < SIDE and 0 <= x < SIDE:\\n            yield y * SIDE + x\\n\\n\\ndef shortest_paths(start, allowed):\\n    distances = {start: 0}\\n    counts = {start: 1}\\n    pending = deque([start])\\n    while pending:\\n        cell = pending.popleft()\\n        step = distances[cell] + 1\\n        for nxt in neighbors(cell):\\n            if nxt not in allowed:\\n                continue\\n            if nxt not in distances:\\n                distances[nxt] = step\\n                counts[nxt] = counts[cell]\\n                pending.append(nxt)\\n            elif distances[nxt] == step:\\n                counts[nxt] += counts[cell]\\n    return distances, counts\\n\\n\\ndef matching_orders(start, goal, marked, target_distances):\\n    \\"\\"\\"Derive the priority constraints imposed by each choice on this path.\\"\\"\\"\\n    precedence = set()\\n    cell = start\\n    while cell != goal:\\n        remaining = target_distances[cell] - 1\\n        choices = [n for n in neighbors(cell) if target_distances.get(n) == remaining]\\n        marked_choices = [n for n in choices if n in marked]\\n        if len(marked_choices) != 1:\\n            raise ValueError(\\"Ambiguous successor inside the labeled path\\")\\n        chosen = marked_choices[0]\\n        winner = DIRECTIONS[chosen - cell]\\n        precedence.update((winner, DIRECTIONS[n - cell]) for n in choices if n != chosen)\\n        cell = chosen\\n    return [order for order in ORDERS if all(order.index(a) < order.index(b) for a, b in precedence)]\\n\\n\\ndef examine(question, answer):\\n    if len(question) != SIDE**2 or len(answer) != SIDE**2:\\n        raise ValueError(\\"Grid has an unexpected length\\")\\n    if question.count(\\"S\\") != 1 or question.count(\\"G\\") != 1:\\n        raise ValueError(\\"Expected one start and one goal\\")\\n    if set(question) - set(\\"# SG\\") or set(answer) - set(\\"# SGo\\"):\\n        raise ValueError(\\"Grid has an unexpected symbol\\")\\n    if answer.replace(\\"o\\", \\" \\") != question:\\n        raise ValueError(\\"Target changed a wall, endpoint, or existing symbol\\")\\n\\n    start, goal = question.index(\\"S\\"), question.index(\\"G\\")\\n    walkable = {i for i, char in enumerate(question) if char != \\"#\\"}\\n    marked = {i for i, char in enumerate(answer) if char in \\"SGo\\"}\\n    distances, counts = shortest_paths(start, walkable)\\n    marked_distances, _ = shortest_paths(start, marked)\\n    if goal not in distances:\\n        raise ValueError(\\"Goal is unreachable\\")\\n    length = distances[goal]\\n    # A shortest route of length d has d+1 distinct cells. Requiring a route\\n    # of that length inside exactly d+1 marked cells excludes stray marks.\\n    if marked_distances.get(goal) != length or len(marked) != length + 1:\\n        raise ValueError(\\"Marked cells do not form a shortest start-to-goal path\\")\\n    to_goal, _ = shortest_paths(goal, walkable)\\n    return (\\n        length, counts[goal],\\n        matching_orders(start, goal, marked, to_goal),\\n        matching_orders(goal, start, marked, distances),\\n    )\\n\\n\\ndef main():\\n    source = ROOT / \\"data/maze/train.csv\\"\\n    lengths, counts = [], []\\n    forward_orders, reverse_orders = Counter(), Counter()\\n    input_symbols, output_symbols = set(), set()\\n    with source.open(encoding=\\"utf-8-sig\\", newline=\\"\\") as handle:\\n        reader = csv.DictReader(handle)\\n        for line, row in enumerate(reader, 2):\\n            question, answer = row[\\"question\\"], row[\\"answer\\"]\\n            try:\\n                length, count, forward, reverse = examine(question, answer)\\n            except ValueError as exc:\\n                raise ValueError(f\\"train.csv line {line}: {exc}\\") from exc\\n            input_symbols.update(question)\\n            output_symbols.update(answer)\\n            lengths.append(length)\\n            counts.append(count)\\n            forward_orders.update(forward)\\n            reverse_orders.update(reverse)\\n    if len(counts) != 1000:\\n        raise ValueError(f\\"Expected 1000 development grids, found {len(counts)}\\")\\n    unique = counts.count(1)\\n    report = {\\n        \\"dataset\\": \\"sapientinc/maze-30x30-hard-1k\\",\\n        \\"revision\\": REVISION,\\n        \\"split\\": \\"train\\",\\n        \\"source_sha256\\": hashlib.sha256(source.read_bytes()).hexdigest(),\\n        \\"grids\\": len(counts),\\n        \\"shape\\": [SIDE, SIDE],\\n        \\"input_symbols\\": sorted(input_symbols),\\n        \\"output_symbols\\": sorted(output_symbols),\\n        \\"target_convention\\": \\"Preserve walls and endpoints; mark interior path cells with o.\\",\\n        \\"valid_shortest_path_labels\\": len(counts),\\n        \\"unique_shortest_paths\\": unique,\\n        \\"multiple_shortest_paths\\": len(counts) - unique,\\n        \\"shortest_path_steps\\": {\\"min\\": min(lengths), \\"max\\": max(lengths)},\\n        \\"max_shortest_path_count\\": max(counts),\\n        \\"tie_break\\": {\\n            \\"method\\": \\"At each cell choose the first neighbor in the listed order that is one step closer to the target. U,D,L,R mean up, down, left, right.\\",\\n            \\"tested_orders_per_direction\\": len(ORDERS),\\n            \\"start_to_goal_perfect_orders\\": [order for order in ORDERS if forward_orders[order] == len(counts)],\\n            \\"goal_to_start_perfect_orders\\": [order for order in ORDERS if reverse_orders[order] == len(counts)],\\n            \\"start_to_goal_best_matches\\": max(forward_orders.values(), default=0),\\n            \\"goal_to_start_best_matches\\": max(reverse_orders.values(), default=0),\\n        },\\n    }\\n    destination = ROOT / \\"results/maze/uniqueness.json\\"\\n    destination.parent.mkdir(parents=True, exist_ok=True)\\n    destination.write_text(json.dumps(report, indent=2) + \\"\\\\n\\", encoding=\\"utf-8\\")\\n    print(json.dumps(report))\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "check_backend.py": "\\"\\"\\"Compare cached GPU attention with literal dense CPU attention on synthetic tokens.\\"\\"\\"\\nimport json\\n\\nimport numpy as np\\nimport torch\\n\\nfrom looped import TorchBlock, dense_numpy\\nfrom weights import build_weights\\n\\n\\ndef main():\\n    w = build_weights(5)\\n    ids = np.random.default_rng(23).integers(len(w[\\"chars\\"]), size=(3, 25))\\n    tested = (0, 1, 2, 4, 8, 16, 32)\\n    with torch.inference_mode():\\n        compiled = TorchBlock(w, torch.float64, torch.device(\\"cuda\\"))\\n        state = compiled.token[torch.as_tensor(ids, device=\\"cuda\\")] + compiled.pos\\n        for t in range(max(tested) + 1):\\n            if t in tested:\\n                dense = dense_numpy(w, ids, t)\\n                actual = (state @ compiled.readout + compiled.bias).cpu().numpy()\\n                np.testing.assert_array_equal(actual, dense)\\n            if t < max(tested):\\n                state = compiled.step(state)\\n    print(json.dumps({\\"backend_check\\": \\"passed\\", \\"synthetic_grids\\": len(ids),\\n                      \\"dense_cpu_vs_gpu_logits_identical_at\\": tested,\\n                      \\"device\\": torch.cuda.get_device_name(), \\"heads\\": compiled.head_types}))\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "evaluate.py": "\\"\\"\\"Evaluate one official Maze-Hard split in FP64 on a CUDA device.\\"\\"\\"\\n\\nimport argparse\\nimport csv\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport time\\n\\n\\nSIDE = 30\\nDATASET = \\"sapientinc/maze-30x30-hard-1k\\"\\nREVISION = \\"549754de3d67eebe57b6b22c7d226b9412d55b07\\"\\nTRAIN_SHA256 = \\"25f9e39b5aee16967da41ba63b2d1d75cf608c2360d8a1419d827f9859dbafa0\\"\\n\\n\\ndef tensor_items(value, name=\\"\\"):\\n    \\"\\"\\"Yield named weight tensors in a stable order across processes.\\"\\"\\"\\n    import numpy as np\\n\\n    if isinstance(value, dict):\\n        for key in sorted(value):\\n            yield from tensor_items(value[key], f\\"{name}/{key}\\")\\n    elif isinstance(value, (tuple, list)):\\n        for index, item in enumerate(value):\\n            yield from tensor_items(item, f\\"{name}/{index}\\")\\n    elif isinstance(value, np.ndarray):\\n        yield name, value\\n\\n\\ndef weight_summary(weights):\\n    import numpy as np\\n\\n    digest = hashlib.sha256()\\n    total = nonzero = 0\\n    for name, value in tensor_items(weights):\\n        arr = np.ascontiguousarray(value, dtype=value.dtype.newbyteorder(\\"<\\"))\\n        header = json.dumps([name, arr.dtype.str, arr.shape], separators=(\\",\\", \\":\\")).encode()\\n        digest.update(len(header).to_bytes(8, \\"big\\"))\\n        digest.update(header)\\n        digest.update(arr.tobytes())\\n        total += arr.size\\n        nonzero += np.count_nonzero(arr)\\n    if not total:\\n        raise ValueError(\\"The model contains no weight tensors\\")\\n    return {\\"tensor_sha256\\": digest.hexdigest(), \\"parameters\\": int(total), \\"nonzero_parameters\\": int(nonzero)}\\n\\n\\ndef source_path(root, split):\\n    filename = \\"train.csv\\" if split == \\"dev\\" else \\"test.csv\\"\\n    path = root / \\"data\\" / \\"maze\\" / filename\\n    if path.is_file():\\n        return path\\n    from huggingface_hub import hf_hub_download\\n\\n    return Path(hf_hub_download(repo_id=DATASET, repo_type=\\"dataset\\", revision=REVISION, filename=filename))\\n\\n\\ndef load_split(path, chars, outputs):\\n    import numpy as np\\n\\n    def lookup(alphabet):\\n        table = np.full(256, -1, dtype=np.int64)\\n        for index, symbol in enumerate(alphabet):\\n            table[ord(symbol)] = index\\n        return table\\n\\n    input_table, output_table = lookup(chars), lookup(outputs)\\n    questions, answers = [], []\\n    with path.open(encoding=\\"utf-8-sig\\", newline=\\"\\") as handle:\\n        for row in csv.DictReader(handle):\\n            q, a = row[\\"question\\"], row[\\"answer\\"]\\n            if len(q) != SIDE**2 or len(a) != SIDE**2:\\n                raise ValueError(\\"Unexpected official grid dimensions\\")\\n            questions.append(input_table[np.frombuffer(q.encode(\\"ascii\\"), dtype=np.uint8)])\\n            answers.append(output_table[np.frombuffer(a.encode(\\"ascii\\"), dtype=np.uint8)])\\n    if len(questions) != 1000:\\n        raise ValueError(\\"Expected 1,000 official mazes\\")\\n    inputs, labels = np.stack(questions), np.stack(answers)\\n    if np.any(inputs < 0) or np.any(labels < 0):\\n        raise ValueError(\\"Unexpected character in the official dataset\\")\\n    return inputs, labels\\n\\n\\ndef grade(predictions, targets, checkpoints):\\n    import numpy as np\\n\\n    reference = predictions[checkpoints[0]]\\n    all_stable = np.ones(len(targets), dtype=bool)\\n    summary = {}\\n    for rounds in checkpoints:\\n        result = np.asarray(predictions[rounds])\\n        if result.shape != targets.shape or result.dtype != np.int64:\\n            raise ValueError(\\"The runner must return one integer prediction per grid cell\\")\\n        correct = np.all(result == targets, axis=1)\\n        stable = np.all(result == reference, axis=1)\\n        all_stable &= stable\\n        summary[str(rounds)] = {\\n            \\"solved\\": int(correct.sum()),\\n            \\"exact_grid_accuracy\\": float(correct.mean()),\\n            \\"same_grid_as_first_checkpoint\\": int(stable.sum()),\\n        }\\n    return {\\n        \\"grids\\": len(targets),\\n        \\"by_checkpoint\\": summary,\\n        \\"identical_grids_across_all_checkpoints\\": int(all_stable.sum()),\\n        \\"all_readouts_fixed\\": bool(all_stable.all()),\\n    }\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\"--split\\", required=True, choices=(\\"dev\\", \\"test\\"))\\n    parser.add_argument(\\"--batch-size\\", type=int, default=64)\\n    parser.add_argument(\\"--root\\", type=Path, default=Path.cwd(), help=\\"Project root containing data/ and results/.\\")\\n    args = parser.parse_args()\\n    if args.batch_size < 1:\\n        parser.error(\\"--batch-size must be positive\\")\\n\\n    os.environ[\\"OMP_NUM_THREADS\\"] = \\"4\\"\\n    os.environ[\\"MKL_NUM_THREADS\\"] = \\"4\\"\\n    os.environ[\\"OPENBLAS_NUM_THREADS\\"] = \\"4\\"\\n    import torch\\n\\n    torch.set_num_threads(4)\\n    torch.set_num_interop_threads(1)\\n    if not torch.cuda.is_available():\\n        raise RuntimeError(\\"Maze-Hard evaluation requires an active CUDA GPU\\")\\n    torch.backends.cuda.matmul.allow_tf32 = False\\n    torch.backends.cudnn.allow_tf32 = False\\n    if __package__:\\n        from .looped import gpu_forward\\n        from .weights import build_weights\\n    else:\\n        from looped import gpu_forward\\n        from weights import build_weights\\n\\n    weights = build_weights(SIDE)\\n    model = weight_summary(weights)\\n    output_dir = args.root / \\"results\\" / \\"maze\\"\\n    output_dir.mkdir(parents=True, exist_ok=True)\\n    destination = output_dir / f\\"{args.split}.json\\"\\n    if args.split == \\"test\\":\\n        if destination.exists():\\n            raise FileExistsError(\\"Official TEST results already exist in this run directory\\")\\n        # Obtain the one-shot marker before looking up or opening TEST. A failed\\n        # run keeps its marker so that the reason can be reviewed before a retry.\\n        with (output_dir / \\"test.started\\").open(\\"x\\", encoding=\\"utf-8\\") as marker:\\n            marker.write(model[\\"tensor_sha256\\"] + \\"\\\\n\\")\\n\\n    data = source_path(args.root, args.split)\\n    data_hash = hashlib.sha256(data.read_bytes()).hexdigest()\\n    if args.split == \\"dev\\" and data_hash != TRAIN_SHA256:\\n        raise ValueError(\\"The development CSV differs from the audited split\\")\\n    ids, labels = load_split(data, weights[\\"chars\\"], weights[\\"outputs\\"])\\n    n = ids.shape[1]\\n    checkpoints = (2 * n, 4 * n, 8 * n)\\n    torch.cuda.synchronize()\\n    start = time.perf_counter()\\n    info = {}\\n    with torch.inference_mode():\\n        predictions = gpu_forward(weights, ids, checkpoints, dtype=\\"float64\\", batch_size=args.batch_size,\\n                                  diagnostics=info)\\n    torch.cuda.synchronize()\\n    elapsed = time.perf_counter() - start\\n    if args.split == \\"test\\":\\n        batches = info.pop(\\"batches\\")\\n        info.update({\\n            \\"batch_count\\": len(batches),\\n            \\"batches_with_exact_full_state_fixed_point\\": sum(b[\\"full_state_fixed\\"] for b in batches),\\n            \\"sum_of_evaluated_blocks_across_batches\\": sum(b[\\"evaluated_blocks\\"] for b in batches),\\n            \\"max_blocks_evaluated_in_a_batch\\": max(b[\\"evaluated_blocks\\"] for b in batches),\\n        })\\n    report = {\\n        \\"split\\": args.split,\\n        \\"dataset\\": DATASET,\\n        \\"revision\\": REVISION,\\n        \\"source_sha256\\": data_hash,\\n        \\"model\\": model,\\n        \\"loop_checkpoints\\": list(checkpoints),\\n        \\"dtype\\": \\"float64\\",\\n        \\"allow_tf32\\": False,\\n        \\"device\\": torch.cuda.get_device_name(),\\n        \\"torch_version\\": str(torch.__version__),\\n        \\"cuda_version\\": torch.version.cuda,\\n        \\"batch_size\\": args.batch_size,\\n        \\"inference_seconds\\": elapsed,\\n        \\"diagnostics\\": info,\\n        **grade(predictions, labels, checkpoints),\\n    }\\n    encoded = json.dumps(report, indent=2, allow_nan=False) + \\"\\\\n\\"\\n    tmp = destination.with_suffix(\\".json.tmp\\")\\n    tmp.write_text(encoded, encoding=\\"utf-8\\")\\n    tmp.replace(destination)\\n    print(encoded, end=\\"\\", flush=True)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "looped.py": "\\"\\"\\"Generic inference for a residual softmax-attention/ReLU block with tied weights.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport math\\n\\nimport numpy as np\\n\\n\\ndef positions(weights):\\n    return (weights[\\"row\\"][:, None, :] + weights[\\"col\\"][None, :, :]).reshape(\\n        -1, weights[\\"token\\"].shape[-1]\\n    )\\n\\n\\ndef dense_numpy(weights, ids, rounds):\\n    \\"\\"\\"Literal float64 implementation for small independent equivalence checks.\\"\\"\\"\\n    h = weights[\\"token\\"][ids] + positions(weights)\\n    for _ in range(rounds):\\n        for layer in weights[\\"layers\\"]:\\n            update = np.zeros_like(h)\\n            for q, k, v, o in zip(*(layer[key] for key in (\\"q\\", \\"k\\", \\"v\\", \\"o\\"))):\\n                scores = (h @ q) @ (h @ k).swapaxes(-1, -2) / math.sqrt(q.shape[-1])\\n                exp = np.exp(scores - scores.max(axis=-1, keepdims=True))\\n                update += ((exp / exp.sum(axis=-1, keepdims=True)) @ (h @ v)) @ o\\n            h = h + update\\n            h = h + np.maximum(0, h @ layer[\\"w1\\"] + layer[\\"b1\\"]) @ layer[\\"w2\\"] + layer[\\"b2\\"]\\n    return h @ weights[\\"readout\\"] + weights[\\"bias\\"]\\n\\n\\nclass TorchBlock:\\n    \\"\\"\\"Prepare invariant attention from weight dependencies, without interpreting tokens.\\"\\"\\"\\n\\n    def __init__(self, w, dtype, device):\\n        import torch\\n\\n        self.torch = torch\\n        self.tensor = lambda a: torch.as_tensor(a, dtype=dtype, device=device)\\n        self.token = self.tensor(w[\\"token\\"])\\n        self.pos = self.tensor(positions(w))\\n        self.readout = self.tensor(w[\\"readout\\"])\\n        self.bias = self.tensor(w[\\"bias\\"])\\n        variable = np.any(w[\\"token\\"] != w[\\"token\\"][:1], axis=0)\\n        for layer in w[\\"layers\\"]:\\n            variable |= np.any(layer[\\"o\\"] != 0, axis=(0, 1))\\n            variable |= np.any(layer[\\"w2\\"] != 0, axis=0) | (layer[\\"b2\\"] != 0)\\n\\n        reference = self.token[0] + self.pos\\n        self.layers = []\\n        self.head_types = []\\n        for layer in w[\\"layers\\"]:\\n            heads = []\\n            for q, k, v, o in zip(*(layer[key] for key in (\\"q\\", \\"k\\", \\"v\\", \\"o\\"))):\\n                keep = np.any(v != 0, axis=0) & np.any(o != 0, axis=1)\\n                if not np.any(keep):\\n                    continue\\n                scale = math.sqrt(q.shape[1])\\n                static = not (np.any(q[variable] != 0) or np.any(k[variable] != 0))\\n                q, k = self.tensor(q), self.tensor(k)\\n                route = attention = None\\n                if static:\\n                    scores = (reference @ q) @ (reference @ k).T / scale\\n                    attention = scores.softmax(dim=-1)\\n                    maxima, indices = attention.max(dim=-1)\\n                    if torch.all(maxima == 1).item() and torch.count_nonzero(attention).item() == len(indices):\\n                        route, attention = indices, None\\n                heads.append((q, k, self.tensor(v[:, keep].copy()), self.tensor(o[keep].copy()),\\n                              scale, route, attention))\\n                self.head_types.append(\\"exact one-hot\\" if route is not None else\\n                                       \\"constant dense\\" if static else \\"dynamic dense\\")\\n            ff = [self.tensor(layer[key]) for key in (\\"w1\\", \\"b1\\", \\"w2\\", \\"b2\\")]\\n            projection = torch.cat([head[3] for head in heads], dim=0) if heads else None\\n            self.layers.append((heads, projection, ff))\\n\\n    def step(self, h):\\n        torch = self.torch\\n        for heads, projection, (w1, b1, w2, b2) in self.layers:\\n            contributions = []\\n            for q, k, v, _, scale, route, attention in heads:\\n                values = h @ v\\n                if route is not None:\\n                    values = values.index_select(1, route)\\n                elif attention is not None:\\n                    values = attention @ values\\n                else:\\n                    scores = (h @ q) @ (h @ k).transpose(-1, -2) / scale\\n                    values = scores.softmax(dim=-1) @ values\\n                contributions.append(values)\\n            if contributions:\\n                h = h + torch.cat(contributions, dim=-1) @ projection\\n            h = h + torch.relu(h @ w1 + b1) @ w2 + b2\\n        return h\\n\\n\\ndef gpu_forward(w, ids, checkpoints, dtype=\\"float64\\", batch_size=64, diagnostics=None):\\n    \\"\\"\\"Evaluate fixed loop budgets; elide repeats only after an exact one-step identity.\\"\\"\\"\\n    import torch\\n\\n    if not torch.cuda.is_available():\\n        raise RuntimeError(\\"CUDA device required for the benchmark\\")\\n    milestones = sorted(set(checkpoints))\\n    if not milestones or milestones[0] < 0 or batch_size < 1:\\n        raise ValueError(\\"invalid checkpoint or batch size\\")\\n    ids = np.asarray(ids, dtype=np.int64)\\n    device = torch.device(\\"cuda\\")\\n    results = {t: [] for t in milestones}\\n    steps = []\\n    with torch.inference_mode():\\n        model = TorchBlock(w, getattr(torch, dtype), device)\\n        for start in range(0, len(ids), batch_size):\\n            batch = torch.as_tensor(ids[start:start + batch_size], device=device)\\n            h = model.token[batch] + model.pos\\n            t = 0\\n            fixed = False\\n            for target in milestones:\\n                while t < target and not fixed:\\n                    new = model.step(h)\\n                    t += 1\\n                    if t % 16 == 0:\\n                        fixed = torch.equal(new, h)\\n                    h = new\\n                decoded = (h @ model.readout + model.bias).argmax(dim=-1)\\n                results[target].append(decoded.cpu().numpy())\\n            steps.append({\\"items\\": len(batch), \\"evaluated_blocks\\": t, \\"full_state_fixed\\": fixed})\\n    if diagnostics is not None:\\n        diagnostics.update({\\"heads\\": model.head_types, \\"batches\\": steps})\\n    return {t: np.concatenate(rows) for t, rows in results.items()}\\n", "test_weights.py": "\\"\\"\\"Handmade component and end-to-end checks, independent of benchmark data.\\"\\"\\"\\n\\nimport unittest\\n\\nimport numpy as np\\n\\nfrom looped import dense_numpy\\nfrom weights import D_HEAD, DIRECTIONS, build_weights\\n\\n\\ndef ids_for(weights, rows):\\n    symbols = weights[\\"chars\\"]\\n    return np.array([[symbols.index(char) for char in \\"\\".join(rows)]])\\n\\n\\ndef output_for(weights, ids, rounds):\\n    indices = dense_numpy(weights, ids, rounds).argmax(axis=-1)[0]\\n    return \\"\\".join(weights[\\"outputs\\"][i] for i in indices)\\n\\n\\nclass MazeWeightsTest(unittest.TestCase):\\n    def test_initial_readout(self):\\n        rows = [\\"S \\", \\"#G\\"]\\n        weights = build_weights(2)\\n        self.assertEqual(output_for(weights, ids_for(weights, rows), 0), \\"\\".join(rows))\\n\\n    def test_static_attention_selectors(self):\\n        # Check all four edges and corners. A query beyond the grid must read\\n        # its own edge cell. The test explicitly checks floating-point softmax.\\n        for side in (3, 30):\\n            weights = build_weights(side)\\n            embeddings = weights[\\"token\\"][0] + weights[\\"row\\"][:, None] + weights[\\"col\\"][None, :]\\n            embeddings = embeddings.reshape(side * side, -1)\\n            layer = weights[\\"layers\\"][0]\\n            y, x = np.indices((side, side))\\n            for dtype in (np.float32, np.float64):\\n                h = embeddings.astype(dtype)\\n                for direction, (dy, dx) in enumerate(DIRECTIONS):\\n                    q = h @ layer[\\"q\\"][direction].astype(dtype)\\n                    k = h @ layer[\\"k\\"][direction].astype(dtype)\\n                    scores = (q @ k.T) / dtype(np.sqrt(D_HEAD))\\n                    probabilities = np.exp(scores - scores.max(axis=1, keepdims=True))\\n                    probabilities /= probabilities.sum(axis=1, keepdims=True)\\n                    target = np.clip(y + dy, 0, side - 1) * side + np.clip(x + dx, 0, side - 1)\\n                    np.testing.assert_array_equal(probabilities.argmax(axis=1), target.ravel())\\n                    self.assertEqual(np.count_nonzero(probabilities), side * side)\\n\\n    def test_canonical_ties_and_walls(self):\\n        cases = [\\n            ([\\"S  \\", \\"   \\", \\"  G\\"], [\\"S  \\", \\"o  \\", \\"ooG\\"]),\\n            ([\\"  G\\", \\"   \\", \\"S  \\"], [\\"  G\\", \\"  o\\", \\"Soo\\"]),\\n            ([\\"#####\\", \\"# S #\\", \\"# # #\\", \\"# G #\\", \\"#####\\"],\\n             [\\"#####\\", \\"#oS #\\", \\"#o# #\\", \\"#oG #\\", \\"#####\\"]),\\n            ([\\"#####\\", \\"#   #\\", \\"#S#G#\\", \\"#   #\\", \\"#####\\"],\\n             [\\"#####\\", \\"#   #\\", \\"#S#G#\\", \\"#ooo#\\", \\"#####\\"]),\\n            ([\\"##S \\", \\" G##\\", \\"####\\", \\"####\\"], [\\"##S \\", \\" G##\\", \\"####\\", \\"####\\"]),\\n        ]\\n        for rows, expected in cases:\\n            with self.subTest(rows=rows):\\n                weights = build_weights(len(rows))\\n                ids = ids_for(weights, rows)\\n                for rounds in (2 * ids.size, 4 * ids.size):\\n                    self.assertEqual(output_for(weights, ids, rounds), \\"\\".join(expected))\\n\\n\\nif __name__ == \\"__main__\\":\\n    unittest.main()\\n", "weights.py": "\\"\\"\\"Analytic weights for a recurrent softmax-attention/ReLU transformer.\\"\\"\\"\\n\\nimport numpy as np\\n\\n\\nCHARS = \\" #SG\\"\\nOUTPUTS = \\" #SGo\\"\\nD_MODEL = 24\\nHEADS = 4\\nD_HEAD = D_MODEL // HEADS\\nALPHA = 1024\\n\\n# Indices in the shared residual stream. Two trailing features are unused.\\nONE, ROW, COL, NORM2, WALL, START, GOAL, REACHED, PATH = range(9)\\nPARENT = (9, 10, 11, 12)\\nSEND = (13, 14, 15, 16)\\nNEAR = (17, 18, 19, 20)\\nINCOMING = 21\\n\\n# The direction order is fixed by the development-split audit. An entry in\\n# OPPOSITE indexes the direction in which that neighbor sends back to us.\\nDIRECTIONS = ((1, 0), (0, -1), (0, 1), (-1, 0))\\nOPPOSITE = (3, 2, 1, 0)\\n\\n\\ndef _layer(width):\\n    return {\\n        \\"q\\": np.zeros((HEADS, D_MODEL, D_HEAD)),\\n        \\"k\\": np.zeros((HEADS, D_MODEL, D_HEAD)),\\n        \\"v\\": np.zeros((HEADS, D_MODEL, D_HEAD)),\\n        \\"o\\": np.zeros((HEADS, D_HEAD, D_MODEL)),\\n        \\"w1\\": np.zeros((D_MODEL, width)),\\n        \\"b1\\": np.zeros(width),\\n        \\"w2\\": np.zeros((width, D_MODEL)),\\n        \\"b2\\": np.zeros(D_MODEL),\\n    }\\n\\n\\ndef build_weights(side):\\n    \\"\\"\\"Return a single shared block, its embeddings and its linear readout.\\"\\"\\"\\n    if not isinstance(side, (int, np.integer)) or side < 1:\\n        raise ValueError(\\"side must be a positive integer\\")\\n\\n    token = np.zeros((len(CHARS), D_MODEL))\\n    token[:, ONE] = 1\\n    token[CHARS.index(\\"#\\"), WALL] = 1\\n    token[CHARS.index(\\"S\\"), [START, PATH]] = 1\\n    token[CHARS.index(\\"G\\"), [GOAL, REACHED]] = 1\\n\\n    position = np.arange(side, dtype=np.float64)\\n    row = np.zeros((side, D_MODEL))\\n    col = np.zeros((side, D_MODEL))\\n    row[:, ROW] = col[:, COL] = position\\n    row[:, NORM2] = col[:, NORM2] = position**2\\n\\n    flood = _layer(10)\\n    # Q.K/sqrt(d_head) is -alpha * squared distance to the requested\\n    # neighbor, up to an additive constant shared by all keys in this row.\\n    score_scale = ALPHA * np.sqrt(D_HEAD)\\n    for direction, (dr, dc) in enumerate(DIRECTIONS):\\n        q, k = flood[\\"q\\"][direction], flood[\\"k\\"][direction]\\n        q[ROW, 0] = q[COL, 1] = 2 * score_scale\\n        q[ONE, :3] = (2 * dr * score_scale, 2 * dc * score_scale, -score_scale)\\n        k[ROW, 0] = k[COL, 1] = k[NORM2, 2] = 1\\n\\n        v, o = flood[\\"v\\"][direction], flood[\\"o\\"][direction]\\n        v[REACHED, 0] = v[SEND[OPPOSITE[direction]], 1] = 1\\n        o[0, NEAR[direction]] = o[1, INCOMING] = 1\\n\\n        # Unit direction turns on only for the first eligible neighbor, and\\n        # only at this cell\'s first arrival. The residual latches its result.\\n        w1, w2 = flood[\\"w1\\"], flood[\\"w2\\"]\\n        w1[NEAR[direction], direction] = 1\\n        w1[list(NEAR[:direction]), direction] = -1\\n        w1[[WALL, REACHED], direction] = -1\\n        w2[direction, [PARENT[direction], REACHED]] = 1\\n\\n        # Clear the nonnegative attention scratch fields for the next round.\\n        clear_near = 4 + direction\\n        w1[NEAR[direction], clear_near] = 1\\n        w2[clear_near, NEAR[direction]] = -1\\n\\n    # path\' = min(1, path + incoming). Reuse the incoming scratch-clear unit.\\n    flood[\\"w1\\"][INCOMING, 8] = 1\\n    flood[\\"w2\\"][8, [INCOMING, PATH]] = (-1, 1)\\n    flood[\\"w1\\"][[INCOMING, PATH], 9] = 1\\n    flood[\\"b1\\"][9] = -1\\n    flood[\\"w2\\"][9, PATH] = -1\\n\\n    route = _layer(4)\\n    for direction in range(HEADS):\\n        # send\' = send OR (path AND parent), with irreversible parent/path.\\n        route[\\"w1\\"][[PATH, PARENT[direction]], direction] = 1\\n        route[\\"w1\\"][SEND[direction], direction] = -1\\n        route[\\"b1\\"][direction] = -1\\n        route[\\"w2\\"][direction, SEND[direction]] = 1\\n\\n    readout = np.zeros((D_MODEL, len(OUTPUTS)))\\n    bias = np.zeros(len(OUTPUTS))\\n    bias[OUTPUTS.index(\\" \\")] = 0.5\\n    readout[PATH, OUTPUTS.index(\\"o\\")] = 1\\n    for feature, char in ((WALL, \\"#\\"), (START, \\"S\\"), (GOAL, \\"G\\")):\\n        readout[feature, OUTPUTS.index(char)] = 2\\n\\n    return {\\"chars\\": CHARS, \\"outputs\\": OUTPUTS, \\"token\\": token, \\"row\\": row,\\n            \\"col\\": col, \\"layers\\": [flood, route], \\"readout\\": readout, \\"bias\\": bias}\\n"}'), 'd405a50d4c12ba7323427a495dc26b01162af73047a3e44d806a0adf408937b1')
